-- entity-engine partitions: generated by `cli entities plan --write`; forward-only; immutable once on origin/main.
-- Reviewed like a hand-written migration. No transaction control.

-- Backfill (hand-written, reviewed): a transfer recorded before accounts were kept arrived on the workspace's bank feed when that
-- workspace has exactly one (SePay or Casso connection); with none or several, which account is not known, so it stays null.
UPDATE public."records_payment_transaction" t
SET data = t.data || jsonb_build_object('connectionId', c.id::text)
FROM (
    SELECT workspace_id, (array_agg(id))[1] AS id
    FROM public.connections
    WHERE provider IN ('sepay', 'casso')
    GROUP BY workspace_id
    HAVING count(*) = 1
) c
WHERE t.workspace_id = c.workspace_id AND (t.data->>'connectionId') IS NULL;

-- An order already paid keeps the account of the transaction that paid it.
UPDATE public."records_sales_order" o
SET data = o.data || jsonb_build_object('paidConnectionId', t.data->>'connectionId')
FROM public."records_payment_transaction" t
WHERE t.workspace_id = o.workspace_id
  AND (t.data->>'orderId') = o.id::text
  AND (t.data->>'connectionId') IS NOT NULL
  AND (o.data->>'paidConnectionId') IS NULL;

-- add_check public.records_sales_order:constraint:records_sales_order_qr_connection_id_chk: added NOT VALID, then validated
ALTER TABLE public."records_sales_order" ADD CONSTRAINT "records_sales_order_qr_connection_id_chk" CHECK ((data->>'qrConnectionId') IS NULL OR ((data->>'qrConnectionId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) NOT VALID;
ALTER TABLE public."records_sales_order" VALIDATE CONSTRAINT "records_sales_order_qr_connection_id_chk";
-- add_check public.records_sales_order:constraint:records_sales_order_paid_connection_id_chk: added NOT VALID, then validated
ALTER TABLE public."records_sales_order" ADD CONSTRAINT "records_sales_order_paid_connection_id_chk" CHECK ((data->>'paidConnectionId') IS NULL OR ((data->>'paidConnectionId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) NOT VALID;
ALTER TABLE public."records_sales_order" VALIDATE CONSTRAINT "records_sales_order_paid_connection_id_chk";
-- add_check public.records_payment_transaction:constraint:records_payment_transaction_connection_id_chk: added NOT VALID, then validated
ALTER TABLE public."records_payment_transaction" ADD CONSTRAINT "records_payment_transaction_connection_id_chk" CHECK ((data->>'connectionId') IS NULL OR ((data->>'connectionId') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')) NOT VALID;
ALTER TABLE public."records_payment_transaction" VALIDATE CONSTRAINT "records_payment_transaction_connection_id_chk";
